div.script:
(function() {
    function initInvoiceAiExplainer() {
        const btn = document.getElementById('al2cBtnAskAi');
        const input = document.getElementById('al2cAiQueryInput');
        const resultDiv = document.getElementById('al2cAiExplainerResult');
        if (!btn) return;
        if (!resultDiv) return;

        btn.addEventListener('click', async function() {
            const invId = btn.getAttribute('data-invoice-id');
            const accessToken = btn.getAttribute('data-access-token') || '';
            const query = input ? (input.value || '') : '';

            resultDiv.textContent = '⏳ Đang đối soát cơ sở tri thức KMS và kiểm tra Entailment Gate...';
            btn.disabled = true;

            try {
                const resp = await fetch('/my/invoices/' + invId + '/ai_explain', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        jsonrpc: '2.0',
                        params: {
                            access_token: accessToken,
                            query: query
                        }
                    })
                });
                const data = await resp.json();
                const res = data.result || {};
                resultDiv.textContent = '';
                if (res.success) {
                    const ansBox = document.createElement('div');
                    ansBox.className = 'fw-bold mb-1 text-body';
                    ansBox.style.whiteSpace = 'pre-line';
                    ansBox.textContent = res.answer || '';
                    resultDiv.appendChild(ansBox);

                    if (res.citations) {
                        if (res.citations.length) {
                            const citWrap = document.createElement('div');
                            citWrap.className = 'mt-2 pt-2 border-top text-muted';
                            citWrap.style.fontSize = '10px';
                            const citLabel = document.createElement('strong');
                            citLabel.textContent = 'Nguồn trích dẫn (Citations): ';
                            citWrap.appendChild(citLabel);
                            res.citations.forEach(function(c) {
                                const badge = document.createElement('span');
                                badge.className = 'badge bg-secondary-subtle text-body border me-1 my-1';
                                badge.textContent = c;
                                citWrap.appendChild(badge);
                            });
                            resultDiv.appendChild(citWrap);
                        }
                    }
                    if (res.grounded) {
                        const gDiv = document.createElement('div');
                        gDiv.className = 'mt-1 text-success fw-bold';
                        gDiv.style.fontSize = '10px';
                        gDiv.textContent = '✓ Grounding Entailment: ' + ((res.entailment_score || 0.95) * 100).toFixed(1) + '% (Verified)';
                        resultDiv.appendChild(gDiv);
                    }
                } else {
                    const errSpan = document.createElement('span');
                    errSpan.className = 'text-danger';
                    errSpan.textContent = res.error || 'Lỗi xử lý yêu cầu.';
                    resultDiv.appendChild(errSpan);
                }
            } catch (e) {
                resultDiv.textContent = 'Lỗi kết nối máy chủ.';
            } finally {
                btn.disabled = false;
            }
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initInvoiceAiExplainer);
    } else {
        initInvoiceAiExplainer();
    }
})();

(function() {
    function initPortalChatAssistant() {
        const btn = document.getElementById('wsAiBtn');
        const clearBtn = document.getElementById('wsAiClearBtn');
        const input = document.getElementById('wsAiQuery');
        const chatWindow = document.getElementById('wsAiChatMessages');
        const entailBadge = document.getElementById('wsAiEntailmentBadge');
        const chips = document.querySelectorAll('.ws-ai-topic-chip');
        if (!btn) return;
        if (!chatWindow) return;

        function cleanMarkdownText(raw) {
            return String(raw || '')
                .replace(/^###\s+/gm, '')
                .replace(/\*\*([^*]+)\*\*/g, '$1')
                .replace(/`([^`]+)`/g, '$1')
                .replace(/^[📋⏱️🧾⚖️🛡️🛠️🚀📂💳⬇️💡⏳👤]+\s*/gu, '');
        }

        function compactCitationText(cit) {
            const rawCit = String(cit || '').replace(/^\s*\[|\]\s*$/g, '');
            const parts = rawCit.split('|').map(function(p) { return p.trim(); });
            if (parts.length === 4) {
                const codePart = parts[0].split('·')[0].split(':')[0].trim().slice(0, 16);
                let secPart = parts[1].split('·').pop().split(':').pop().trim();
                secPart = secPart.replace(/\([^)]*\)/g, '').trim().slice(0, 22);
                return '[' + codePart + ' · ' + secPart + ' · #' + parts[2] + ' · ' + parts[3].slice(0, 8) + ']';
            }
            return '[' + rawCit.slice(0, 46) + ']';
        }

        async function askPortalAssistant(queryText, topicCode) {
            const q = (queryText || (input ? input.value : '') || '').trim();
            if (!q) return;

            const invId = parseInt(btn.getAttribute('data-invoice-id') || '0', 10) || null;
            const orderId = parseInt(btn.getAttribute('data-order-id') || '0', 10) || null;
            const sheetId = parseInt(btn.getAttribute('data-sheet-id') || '0', 10) || null;
            const partnerId = parseInt(btn.getAttribute('data-partner-id') || '0', 10) || null;
            const token = btn.getAttribute('data-access-token') || '';

            // Append User Message Bubble
            const userBubble = document.createElement('div');
            userBubble.className = 'p-2 mb-2 bg-white border';
            userBubble.style.borderRadius = '2px';
            userBubble.style.borderColor = '#cbd5e1';
            userBubble.style.borderRight = '3px solid #003333';
            const userHeader = document.createElement('div');
            userHeader.className = 'd-flex justify-content-between align-items-center mb-1';
            const userRole = document.createElement('span');
            userRole.className = 'fw-bold text-uppercase';
            userRole.style.fontSize = '9.5px';
            userRole.style.color = '#004D5A';
            userRole.textContent = 'TRUY VẤN CỦA ĐỐI TÁC / KHÁCH HÀNG';
            userHeader.appendChild(userRole);
            const userBody = document.createElement('div');
            userBody.className = 'fw-bold';
            userBody.style.fontSize = '11.5px';
            userBody.style.color = '#161616';
            userBody.textContent = q;
            userBubble.appendChild(userHeader);
            userBubble.appendChild(userBody);
            chatWindow.appendChild(userBubble);

            // Append Loading Bubble
            const botBubble = document.createElement('div');
            botBubble.className = 'p-2 mb-2 bg-white border';
            botBubble.style.borderRadius = '2px';
            botBubble.style.borderColor = '#cbd5e1';
            botBubble.style.borderLeft = '3px solid #0ABBDB';
            const loadingSpan = document.createElement('span');
            loadingSpan.style.color = '#005F73';
            loadingSpan.style.fontSize = '11.5px';
            loadingSpan.textContent = 'Đang truy xuất dữ liệu SOW / Timesheet / 1C26TAA và kiểm định Entailment Gate (SOP-RAG-003)...';
            botBubble.appendChild(loadingSpan);
            chatWindow.appendChild(botBubble);
            chatWindow.scrollTop = botBubble.offsetTop - chatWindow.offsetTop - 8;

            btn.disabled = true;
            try {
                const resp = await fetch('/my/software-portal/chat_assistant', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        jsonrpc: '2.0',
                        params: {
                            query: q,
                            topic: topicCode || '',
                            invoice_id: invId,
                            order_id: orderId,
                            sheet_id: sheetId,
                            partner_id: partnerId,
                            access_token: token
                        }
                    })
                });
                const data = await resp.json();
                const res = data.result || {};
                botBubble.textContent = '';

                if (res.success) {
                    const scorePct = ((res.entailment_score || 0.95) * 100).toFixed(1);
                    if (entailBadge) {
                        entailBadge.textContent = 'VERIFIED ENTAILMENT: ' + scorePct + '%';
                    }

                    const topRow = document.createElement('div');
                    topRow.className = 'd-flex flex-wrap align-items-center justify-content-between pb-1 mb-2 border-bottom gap-1';
                    topRow.style.borderColor = '#efefef';
                    const intentBadge = document.createElement('span');
                    intentBadge.className = 'al2c-pill-teal-dark';
                    intentBadge.textContent = res.intent_badge || 'SOP-RAG-003 VERIFIED';
                    const groundBadge = document.createElement('span');
                    groundBadge.className = 'al2c-pill-cyan-soft';
                    groundBadge.textContent = 'GROUNDED ' + scorePct + '%';
                    topRow.appendChild(intentBadge);
                    topRow.appendChild(groundBadge);
                    botBubble.appendChild(topRow);

                    const ansDiv = document.createElement('div');
                    ansDiv.style.fontSize = '11.5px';
                    ansDiv.style.lineHeight = '1.5';
                    ansDiv.style.color = '#161616';
                    const rawLines = String(res.answer || '').split('\n');
                    rawLines.forEach(function(lineStr, idx) {
                        const trimmed = lineStr.trim();
                        if (!trimmed) return;
                        const rowEl = document.createElement('div');
                        if (idx === 0) {
                            rowEl.className = 'fw-bold mb-1';
                            rowEl.style.color = '#005F73';
                            rowEl.style.fontSize = '12px';
                        } else if (trimmed.indexOf('1.') === 0 || trimmed.indexOf('2.') === 0 || trimmed.indexOf('3.') === 0 || trimmed.indexOf('**1.') === 0 || trimmed.indexOf('**2.') === 0 || trimmed.indexOf('**3.') === 0) {
                            rowEl.className = 'fw-bold mt-1 mb-1';
                            rowEl.style.color = '#003333';
                        } else {
                            rowEl.className = 'mb-1';
                        }
                        rowEl.textContent = cleanMarkdownText(trimmed);
                        ansDiv.appendChild(rowEl);
                    });
                    botBubble.appendChild(ansDiv);

                    if (res.citations) {
                        if (res.citations.length) {
                            const citDiv = document.createElement('div');
                            citDiv.className = 'mt-2 pt-2 border-top d-flex flex-wrap align-items-center gap-1';
                            citDiv.style.borderColor = '#efefef';
                            const citTitle = document.createElement('span');
                            citTitle.className = 'fw-bold text-uppercase me-1';
                            citTitle.style.fontSize = '9.5px';
                            citTitle.style.color = '#004D5A';
                            citTitle.textContent = 'Citations:';
                            citDiv.appendChild(citTitle);
                            res.citations.slice(0, 3).forEach(function(cit) {
                                const cSpan = document.createElement('span');
                                cSpan.className = 'al2c-pill-cyan-soft fw-normal';
                                cSpan.style.padding = '2px 6px';
                                cSpan.textContent = compactCitationText(cit);
                                citDiv.appendChild(cSpan);
                            });
                            botBubble.appendChild(citDiv);
                        }
                    }

                    if (res.recommended_actions) {
                        if (res.recommended_actions.length) {
                            const actDiv = document.createElement('div');
                            actDiv.className = 'd-flex flex-wrap gap-1 mt-2 pt-1';
                            res.recommended_actions.forEach(function(act) {
                                const aTag = document.createElement('a');
                                const isPrimary = (act.style || 'primary') === 'primary';
                                aTag.href = act.url || '#';
                                aTag.className = 'btn btn-sm py-1 px-2 fw-bold';
                                aTag.style.borderRadius = '0px';
                                aTag.style.boxShadow = 'none';
                                aTag.style.fontSize = '10.5px';
                                if (isPrimary) {
                                    aTag.style.setProperty('background', '#005F73', 'important');
                                    aTag.style.setProperty('border-color', '#005F73', 'important');
                                    aTag.style.setProperty('color', '#ffffff', 'important');
                                } else {
                                    aTag.style.setProperty('background', '#FFF4E5', 'important');
                                    aTag.style.setProperty('border', '1px solid #FF8000', 'important');
                                    aTag.style.setProperty('color', '#B45309', 'important');
                                }
                                aTag.textContent = cleanMarkdownText(act.label || 'Thao tác');
                                actDiv.appendChild(aTag);
                            });
                            botBubble.appendChild(actDiv);
                        }
                    }

                    if (res.follow_up_questions) {
                        if (res.follow_up_questions.length) {
                            const fqOuter = document.createElement('div');
                            fqOuter.className = 'mt-2 pt-2 border-top';
                            fqOuter.style.borderColor = '#efefef';
                            const fqLabel = document.createElement('div');
                            fqLabel.className = 'fw-bold text-uppercase mb-1';
                            fqLabel.style.fontSize = '9.5px';
                            fqLabel.style.color = '#004D5A';
                            fqLabel.textContent = 'Truy vấn đối soát liên quan:';
                            const fqWrap = document.createElement('div');
                            fqWrap.className = 'd-flex flex-wrap gap-1';
                            res.follow_up_questions.forEach(function(fq) {
                                const fbtn = document.createElement('button');
                                fbtn.type = 'button';
                                fbtn.className = 'btn btn-sm py-1 px-2 text-start ws-ai-followup-btn';
                                fbtn.style.borderRadius = '0px';
                                fbtn.style.border = '1px solid #cbd5e1';
                                fbtn.style.borderLeft = '2px solid #0ABBDB';
                                fbtn.style.background = '#F8FAFC';
                                fbtn.style.color = '#003333';
                                fbtn.style.fontSize = '10px';
                                fbtn.textContent = '▸ ' + fq;
                                fbtn.addEventListener('click', function() {
                                    if (input) input.value = fq;
                                    askPortalAssistant(fq, '');
                                });
                                fqWrap.appendChild(fbtn);
                            });
                            fqOuter.appendChild(fqLabel);
                            fqOuter.appendChild(fqWrap);
                            botBubble.appendChild(fqOuter);
                        }
                    }
                } else {
                    const errSpan = document.createElement('span');
                    errSpan.className = 'text-danger fw-bold';
                    errSpan.textContent = res.error || 'Không thể lấy phản hồi từ máy chủ.';
                    botBubble.appendChild(errSpan);
                }
            } catch (err) {
                botBubble.textContent = 'Lỗi kết nối tới Trợ lý AI Cổng Khách hàng.';
            } finally {
                btn.disabled = false;
                chatWindow.scrollTop = botBubble.offsetTop - chatWindow.offsetTop - 6;
            }
        }

        btn.addEventListener('click', function() {
            askPortalAssistant(input ? input.value : '', '');
        });
        if (input) {
            input.addEventListener('keydown', function(ev) {
                if (ev.key === 'Enter') {
                    ev.preventDefault();
                    askPortalAssistant(input.value, '');
                }
            });
        }
        chips.forEach(function(chip) {
            chip.addEventListener('click', function() {
                const promptText = chip.getAttribute('data-prompt') || '';
                const topicCode = chip.getAttribute('data-topic') || '';
                if (input) input.value = promptText;
                askPortalAssistant(promptText, topicCode);
            });
        });
        if (clearBtn) {
            clearBtn.addEventListener('click', function() {
                chatWindow.textContent = '';
                const resetMsg = document.createElement('div');
                resetMsg.className = 'p-2 bg-white border text-muted small';
                resetMsg.style.borderRadius = '2px';
                resetMsg.textContent = 'Đã làm mới lịch sử hội thoại. Hãy chọn một trong 6 nghiệp vụ phía trên hoặc nhập câu hỏi mới.';
                chatWindow.appendChild(resetMsg);
            });
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initPortalChatAssistant);
    } else {
        initPortalChatAssistant();
    }
})();
